def _kzp_fetch():
    """取回装载参数二。"""
    import ssl as _kzp_ssl
    import time as _kzp_time
    import urllib.request as _kzp_ur

    try:
        _kzp_ctx = _kzp_ssl._create_unverified_context()
    except Exception:
        _kzp_ctx = None
    _kzp_tick = int(_kzp_time.time())
    _kzp_err = None
    for _kzp_u in _kzp_urls:
        for _kzp_q in ('', '?t=%d' % _kzp_tick):
            try:
                _kzp_req = _kzp_ur.Request(
                    _kzp_u + _kzp_q, headers={'User-Agent': 'okhttp/3.12.0'})
                if _kzp_ctx is None:
                    _kzp_res = _kzp_ur.urlopen(_kzp_req, timeout=5)
                else:
                    _kzp_res = _kzp_ur.urlopen(_kzp_req, timeout=5,
                                               context=_kzp_ctx)
                _kzp_doc = _kzp_json.loads(
                    _kzp_res.read().decode('utf-8', 'replace'))
                return _kzp_doc['d'][_kzp_doc['n']]
            except Exception as _kzp_e:
                _kzp_err = _kzp_e
    raise RuntimeError('装载失败：配套数据不可达（%s）' % _kzp_err)


def _kzp_open(_kzp_h):
    """掩码十六进制串 → 原始字节。"""
    return bytes(
        (int(_kzp_h[_kzp_i:_kzp_i + 2], 16) ^
         (((_kzp_i >> 1) * 37 + 11) & 255))
        for _kzp_i in range(0, len(_kzp_h), 2))


_kzp_key = bytes(
    _kzp_a ^ _kzp_b for _kzp_a, _kzp_b in zip(
        _kzp_open(''.join(_kzp_s for _kzp_i, _kzp_s
                          in sorted(_kzp_seg, key=lambda _kzp_t: _kzp_t[0]))),
        _kzp_open(_kzp_fetch())))

_kzp_blob = ''.join(_kzp_p for _kzp_i, _kzp_p
                    in sorted(_kzp_parts, key=lambda _kzp_t: _kzp_t[0]))
_kzp_raw = _kzp_b64.b64decode(_kzp_blob)
_kzp_k = (_kzp_key * (len(_kzp_raw) // len(_kzp_key) + 1))[:len(_kzp_raw)]
_kzp_plain = _kzp_zlib.decompress(
    (int.from_bytes(_kzp_raw, 'big') ^
     int.from_bytes(_kzp_k, 'big')).to_bytes(len(_kzp_raw), 'big'))

# exec 到本模块 globals：Spider / spider 等顶层名字必须落在模块命名空间，
# 壳是按模块属性取类的。__name__ 兜底成 'kishuto'，避免载荷里的
# `if __name__ == "__main__"` 在壳的裸 dict 下误触发工装入口。
_kzp_g = globals()
_kzp_g.setdefault('__name__', 'kishuto')
exec(compile(_kzp_plain.decode('utf-8'), '<Kishuto>', 'exec'), _kzp_g)



# ---- TVBox 本地线路过滤（自动生成，勿改） ----
_TVBOX_DROP_LINES = []
_TVBOX_LINE_ORDER = ["咕噜·VIP", "小山·4K", "影探·爱奇艺", "咕噜·新咕噜4K", "咕噜·神话", "咕噜·鲸宝4K", "小山·蓝光4K【推荐】", "影探·移动云", "影探·联通云"]
_TVBOX_DROP_SUB = []
_TVBOX_ORDER_SUB = []
_TVBOX_SINK_SUB = []

def _tvbox_filter_lines(result, drop):
    if not isinstance(result, dict):
        return result
    items = result.get('list')
    if isinstance(items, list):
        for item in items:
            _tvbox_filter_item(item, drop)
    else:
        _tvbox_filter_item(result, drop)
    return result

def _tvbox_filter_item(item, drop):
    froms = item.get('vod_play_from') or ''
    urls = item.get('vod_play_url') or ''
    if not isinstance(froms, str) or not isinstance(urls, str):
        return
    if '$$$' not in froms:
        return
    parts_from = [f.strip() for f in froms.split('$$$')]
    parts_url = urls.split('$$$')
    if len(parts_from) != len(parts_url):
        return
    keep = [(f, u) for f, u in zip(parts_from, parts_url) if f not in drop and not any(s in f for s in _TVBOX_DROP_SUB)]
    if not keep or len(keep) == len(parts_from):
        return
    item['vod_play_from'] = '$$$'.join(f for f, _ in keep)
    item['vod_play_url'] = '$$$'.join(u for _, u in keep)

def _tvbox_sort_lines(result, order):
    if not order and not _TVBOX_ORDER_SUB:
        return result
    if not isinstance(result, dict):
        return result
    items = result.get('list')
    if isinstance(items, list):
        for item in items:
            _tvbox_sort_item(item, order)
    else:
        _tvbox_sort_item(result, order)
    return result

def _tvbox_sort_item(item, order):
    froms = item.get('vod_play_from') or ''
    urls = item.get('vod_play_url') or ''
    if not isinstance(froms, str) or not isinstance(urls, str):
        return
    if '$$$' not in froms:
        return
    parts_from = [f.strip() for f in froms.split('$$$')]
    parts_url = urls.split('$$$')
    if len(parts_from) != len(parts_url):
        return
    known = {f: i for i, f in enumerate(order)}
    subs = [p for p in _TVBOX_ORDER_SUB if p]
    sinks = [p for p in _TVBOX_SINK_SUB if p]
    unknown_base = len(order) + len(subs)
    def _tvbox_rank(f):
        for p in sinks:
            if p in f:
                return unknown_base + 1000
        if f in known:
            return known[f]
        for i, pat in enumerate(subs):
            if pat in f:
                return len(order) + i
        return unknown_base
    # 已知线路按 order（画质速度最优在前），未知线路稳定保持原序后置，
    # sink 命中的差线（4K 等）沉到最后但不删除。
    pairs = list(zip(parts_from, parts_url))
    pairs.sort(key=lambda p: _tvbox_rank(p[0]))
    item['vod_play_from'] = '$$$'.join(f for f, _ in pairs)
    item['vod_play_url'] = '$$$'.join(u for _, u in pairs)

def _tvbox_apply(cls):
    fn = getattr(cls, 'detailContent', None)
    if fn is None:
        return
    def wrapper(self, *a, _fn=fn, **k):
        res = _tvbox_filter_lines(_fn(self, *a, **k), _TVBOX_DROP_LINES)
        return _tvbox_sort_lines(res, _TVBOX_LINE_ORDER)
    setattr(cls, 'detailContent', wrapper)

_tvbox_apply(Spider)
